CREATE TRIGGER RefPortPolygon_Version_Create
	ON RefPortPolygon
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RPP_PK, 'RPP'
	FROM inserted
GO
CREATE TRIGGER RefPortPolygon_Version_Update
	ON RefPortPolygon
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RPP_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefPortPolygon_DataChangeHistory
	ON RefPortPolygon
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RPP_PK, 'RPP' FROM inserted
	UNION
	SELECT RPP_PK, 'RPP' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefPortPolygon_DataProcessingResult_Delete
	ON RefPortPolygon
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RPP_PK
	END
